CREATE TABLE users (id bigserial PRIMARY KEY, kakao_id text UNIQUE, nickname text NOT NULL, is_guest boolean NOT NULL DEFAULT true, guest_token_hash char(64) UNIQUE, role varchar(10) NOT NULL DEFAULT 'USER', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE games (id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), seed bigint NOT NULL, start_quarter char(5) NOT NULL, last_quarter char(5) NOT NULL, current_turn int NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'PLAYING', ending_type text, version bigint NOT NULL DEFAULT 0, cash bigint NOT NULL, initial_capital bigint NOT NULL, negative_quarters int NOT NULL DEFAULT 0, settings jsonb NOT NULL);
CREATE TABLE game_data_pins (game_id bigint REFERENCES games(id), source text NOT NULL, version_id bigint REFERENCES data_versions(id), PRIMARY KEY(game_id,source,version_id));
CREATE TABLE owners (game_id bigint PRIMARY KEY REFERENCES games(id), name text NOT NULL, background text NOT NULL, cooking int NOT NULL, service int NOT NULL, management int NOT NULL, marketing int NOT NULL, stamina int NOT NULL, network int NOT NULL, focus_stat_1 text, focus_stat_2 text);
CREATE TABLE shops (id bigserial PRIMARY KEY, game_id bigint NOT NULL UNIQUE REFERENCES games(id), area_code text NOT NULL, area_name text NOT NULL, district_code text, service_code text NOT NULL, service_name text NOT NULL, name text NOT NULL, geom geometry(Point,4326) NOT NULL, capital bigint NOT NULL, opened_turn int NOT NULL DEFAULT 0, closed_turn int, area_m2 numeric);
CREATE TABLE rivals (id bigserial PRIMARY KEY, game_id bigint NOT NULL REFERENCES games(id), sbiz_store_id text, is_virtual boolean NOT NULL DEFAULT false, service_code text NOT NULL, geom geometry(Point,4326) NOT NULL, is_franchise boolean NOT NULL DEFAULT false, opened_turn int NOT NULL DEFAULT 0, closed_turn int);
CREATE TABLE turn_decisions (game_id bigint REFERENCES games(id), turn int NOT NULL, price_level text NOT NULL, open_hours int NOT NULL CHECK(open_hours BETWEEN 6 AND 16), staff int NOT NULL CHECK(staff BETWEEN 0 AND 10), marketing bigint NOT NULL CHECK(marketing>=0), owner_activity text NOT NULL, PRIMARY KEY(game_id,turn));
CREATE TABLE turn_results (game_id bigint REFERENCES games(id), turn int NOT NULL, market_size bigint NOT NULL, share double precision NOT NULL, revenue bigint NOT NULL, visitors bigint NOT NULL, cost bigint NOT NULL, profit bigint NOT NULL, area_rank int NOT NULL, stat_changes jsonb NOT NULL, reactions jsonb NOT NULL DEFAULT '[]', response jsonb NOT NULL, PRIMARY KEY(game_id,turn));
CREATE TABLE ledger_entries (id bigserial PRIMARY KEY, game_id bigint NOT NULL REFERENCES games(id), turn int NOT NULL, amount bigint NOT NULL, type text NOT NULL, memo text);
CREATE TABLE idempotency_keys (game_id bigint REFERENCES games(id), key varchar(100) NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(game_id,key));
CREATE TABLE game_settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
-- v1 임의값: 실제 임대 시세가 아닌 자치구별 분기 임대료.
